// Generated by panelkit. Do not edit; edit panelkit/emit.py.
//
// The family's shared panel vocabulary: the palette, the millimetre grid, the
// text kit and the hardware. Every panel in the plugin draws through this and
// nothing else -- no module may call nvgFontFaceId, nvgFontSize,
// nvgTextLetterSpacing, nvgTextBounds, nvgText or loadFont itself. `make panel`
// prints every place that does.
//
// This file is included by every src/<Module>/Panel.hpp, which adds that one
// panel's numbers. Include the Panel.hpp, not this.
//
// Everything below has external linkage (inline or template), so it is defined
// once for the whole plugin. Anything that varies per panel belongs in
// Panel.hpp instead, as `static`.
#pragma once
#include <rack.hpp>

#include <cmath>
#include <cstddef>
#include <memory>
#include <string>
#include <vector>

