// included from anywhere in the plugin without dragging the module in with it.
extern rack::Plugin* pluginInstance;

namespace panel {

using namespace rack;

// --- geometry --------------------------------------------------------------
/** The standard Eurorack 3U face. Panel width is per-module: see Panel.hpp. */
static const float PANEL_H = 128.5000f;  // mm

// --- palette ---------------------------------------------------------------
// `static` because NVGcolor is not a literal type under C++11, which is what
// the Rack SDK compiles plugins as -- so these cannot be inline variables and
// each translation unit gets its own copy. The values are generated, so the
// copies cannot disagree.
static const NVGcolor INK    = nvgRGB(0x18, 0x1e, 0x15);   // engraving ink: the dark bands, and primary text on the face
static const NVGcolor PAPER  = nvgRGB(0xe4, 0xea, 0xe1);   // the face, and primary text on dark ground
static const NVGcolor FELT   = nvgRGB(0xe7, 0xe1, 0xea);   // section blocks
static const NVGcolor BAND   = nvgRGB(0x18, 0x1e, 0x15);   // masthead and footer bands
static const NVGcolor GLASS  = nvgRGB(0x1b, 0x15, 0x1e);   // displays and widget wells
static const NVGcolor RULE   = nvgRGB(0x7b, 0x9a, 0x6d);   // the guilloche: rules, frames, traces
static const NVGcolor LIME   = nvgRGB(0xaa, 0xbe, 0xa1);   // accent on dark ground; LED emitters
static const NVGcolor MINT   = nvgRGB(0xa9, 0xbd, 0xa0);   // affirmatives: outputs
static const NVGcolor CLAY   = nvgRGB(0x99, 0x93, 0x9c);   // action required
static const NVGcolor SAGE   = nvgRGB(0x7b, 0x9a, 0x6d);   // secondary text on dark ground
static const NVGcolor SAGE_DARK = nvgRGB(0x4e, 0x62, 0x45);   // secondary text on the face
static const NVGcolor LIME_DARK = nvgRGB(0x62, 0x7b, 0x57);   // accent text on the face
static const NVGcolor MINT_DARK = nvgRGB(0x59, 0x66, 0x54);   // output text on the face
static const NVGcolor CLAY_DARK = nvgRGB(0x62, 0x5c, 0x65);   // warning text on the face

inline NVGcolor alpha(NVGcolor c, float a) { c.a = a; return c; }

// --- fonts -----------------------------------------------------------------
// UI is Nunito Bold (the silkscreen), read-outs are Share Tech Mono, and
// numerals in a read-out are DSEG7. DSEG7's cmap carries only [0-9 . : -];
// Rack chains NotoSansJP as a fallback onto every font, so a stray '%' in the
// segment face renders as proportional Japanese sans rather than a tofu box.
inline std::string uiFont()   { return asset::system("res/fonts/Nunito-Bold.ttf"); }
inline std::string monoFont() { return asset::system("res/fonts/ShareTechMono-Regular.ttf"); }
inline std::string segFont()  { return asset::system("res/fonts/DSEG7ClassicMini-Bold.ttf"); }

inline Vec mm(float x, float y) { return mm2px(Vec(x, y)); }
inline Rect mmRect(float x, float y, float w, float h) {
	return Rect(mm2px(Vec(x, y)), mm2px(Vec(w, h)));
}

// --- text ------------------------------------------------------------------
// Rack's nanosvg discards <text>, so every word on a family panel is drawn at
// runtime. That makes text drawing the single most repeated thing the plugins
// do, which is why the whole vocabulary for it lives here rather than being
// re-spelled at each call site.

/** The three faces the family uses. */
enum class Face { Ui, Mono, Seg };

inline std::string facePath(Face f) {
	switch (f) {
		case Face::Mono: return monoFont();
		case Face::Seg:  return segFont();
		default:         return uiFont();
	}
}

/** How one run of text is set.
 *
 * Bundled rather than passed as five arguments because two of these are sticky
 * global state on the NVGcontext: a run that sets letter spacing or an
 * alignment and does not put it back silently restyles whatever draws next.
 * Going through TextStyle makes that impossible to forget. */
struct TextStyle {
	Face face = Face::Ui;
	float size = 10.f;
	float tracking = 0.f;
	NVGcolor ink = PAPER;
	int align = NVG_ALIGN_LEFT | NVG_ALIGN_BASELINE;

	TextStyle() {}
	TextStyle(Face face, float size, NVGcolor ink, int align, float tracking = 0.f)
		: face(face), size(size), tracking(tracking), ink(ink), align(align) {}

	/** A copy in a different ink -- the usual reason a call site wants a variant. */
	TextStyle inked(NVGcolor c) const { TextStyle s = *this; s.ink = c; return s; }
	TextStyle aligned(int a) const { TextStyle s = *this; s.align = a; return s; }
	TextStyle sized(float px) const { TextStyle s = *this; s.size = px; return s; }
};

/** Binds a style to the context. False means the face has not loaded yet and the
    caller must draw nothing: nvgText with no face bound is undefined. */
inline bool bindStyle(NVGcontext* vg, const TextStyle& s) {
	std::shared_ptr<window::Font> font = APP->window->loadFont(facePath(s.face));
	if (!font)
		return false;
	nvgFontFaceId(vg, font->handle);
	nvgFontSize(vg, s.size);
	nvgTextAlign(vg, s.align);
	nvgTextLetterSpacing(vg, s.tracking);
	nvgFillColor(vg, s.ink);
	return true;
}

/** Draws one run, then clears the tracking it set. */
inline float text(NVGcontext* vg, const TextStyle& s, float x, float y, const char* str) {
	if (!bindStyle(vg, s))
		return x;
	float end = nvgText(vg, x, y, str, NULL);
	nvgTextLetterSpacing(vg, 0.f);
	return end;
}

inline float text(NVGcontext* vg, const TextStyle& s, float x, float y,
                  const std::string& str) {
	return text(vg, s, x, y, str.c_str());
}

inline float text(NVGcontext* vg, const TextStyle& s, Vec p, const std::string& str) {
	return text(vg, s, p.x, p.y, str.c_str());
}

/** Width of `str` in `s`, in local units. Leaves no tracking behind. */
inline float textWidth(NVGcontext* vg, const TextStyle& s, const std::string& str) {
	if (!bindStyle(vg, s))
		return 0.f;
	float bounds[4];
	nvgTextBounds(vg, 0, 0, str.c_str(), NULL, bounds);
	nvgTextLetterSpacing(vg, 0.f);
	return bounds[2] - bounds[0];
}

/** Draws a run reflected about its anchor -- the maker's mark, and anything else
    that wants a genuine glyph rather than a traced curve. The alignment flips
    with the axis, so the glyph lands on the side of `x` it would have occupied
    unmirrored. */
inline void textMirrored(NVGcontext* vg, const TextStyle& s, float x, float y,
                         const char* str) {
	TextStyle f = s;
	if (f.align & NVG_ALIGN_LEFT)
		f.align = (f.align & ~NVG_ALIGN_LEFT) | NVG_ALIGN_RIGHT;
	else if (f.align & NVG_ALIGN_RIGHT)
		f.align = (f.align & ~NVG_ALIGN_RIGHT) | NVG_ALIGN_LEFT;
	nvgSave(vg);
	nvgTranslate(vg, x, y);
	nvgScale(vg, -1.f, 1.f);
	text(vg, f, 0.f, 0.f, str);
	nvgRestore(vg);
}

/** The uniform scale of the context's current transform. */
inline float transformScale(NVGcontext* vg) {
	float xf[6];
	nvgCurrentTransform(vg, xf);
	return std::sqrt(std::fabs(xf[0] * xf[3] - xf[1] * xf[2]));
}

/** `str` trimmed to `maxWidth` with a trailing ellipsis, remembered until one of
 * its inputs changes.
 *
 * Both halves matter. The measuring is a binary search over codepoint
 * boundaries, not a character-at-a-time trim: a trim costs one text shaping pass
 * per character dropped, which for a long title is forty-odd passes -- every
 * frame, for every row on screen. The cache then takes the steady-state cost to
 * nothing, since the text of a panel changes far more rarely than it is drawn.
 *
 * The transform scale is part of the key because nvgTextBounds quantizes to the
 * rasterized glyph grid: the same string at the same nominal size measures a
 * shade wider at a different rack zoom, and a stale fit would clip. */
/** All-segments-on ghost behind a numeric read-out: every digit becomes an 8.
    This is what sells a seven-segment display -- without it the unlit segments
    are simply absent and the thing reads as text in an odd face. */
inline std::string segGhost(const std::string& s) {
	std::string g = s;
	for (size_t i = 0; i < g.size(); i++)
		if (g[i] >= '0' && g[i] <= '9')
			g[i] = '8';
	return g;
}

/** Draws a numeral in the segment face over its ghost, then its unit in the text
 * face, and returns the x advance.
 *
 * The family's read-out rule in one function: numerals in DSEG7, words in Share
 * Tech Mono. DSEG7's cmap carries only [0-9 . : -], so a unit MUST leave the
 * segment face or Rack's NotoSansJP fallback renders it as Japanese sans. Note
 * also that DSEG7's '.' has zero advance -- it overprints the previous glyph --
 * so "2.997" occupies four cells, not five, and anything measuring these strings
 * has to measure rather than count. */
inline float segValue(NVGcontext* vg, float x, float y, float size,
                      const std::string& num, const std::string& unit, NVGcolor ink) {
	TextStyle seg(Face::Seg, size, alpha(ink, 0.13f),
	              NVG_ALIGN_LEFT | NVG_ALIGN_BASELINE);
	text(vg, seg, x, y, segGhost(num));
	float end = text(vg, seg.inked(ink), x, y, num);
	if (!unit.empty()) {
		TextStyle u(Face::Mono, size * 0.72f, alpha(ink, 0.7f),
		            NVG_ALIGN_LEFT | NVG_ALIGN_BASELINE);
		end = text(vg, u, end + 1.5f, y, unit);
	}
	return end;
}

struct FittedText {
	const std::string& get(NVGcontext* vg, const TextStyle& style,
	                       const std::string& str, float maxWidth) {
		float sc = transformScale(vg);
		if (maxWidth != cachedWidth || style.size != cachedSize
		    || style.face != cachedFace || sc != cachedScale || str != source) {
			source = str;
			cachedWidth = maxWidth;
			cachedSize = style.size;
			cachedFace = style.face;
			cachedScale = sc;
			result = fit(vg, style, str, maxWidth);
		}
		return result;
	}

	/** The uncached form. Prefer get() anywhere this runs per frame. */
	static std::string fit(NVGcontext* vg, const TextStyle& style,
	                       const std::string& str, float maxWidth) {
		if (textWidth(vg, style, str) <= maxWidth)
			return str;

		// Every index at which a UTF-8 codepoint starts, plus the end. Trimming
		// bytes instead would split multi-byte glyphs.
		std::vector<size_t> stops;
		stops.push_back(0);
		for (size_t i = 1; i <= str.size(); i++)
			if (i == str.size() || ((unsigned char) str[i] & 0xC0) != 0x80)
				stops.push_back(i);

		static const char* const ELLIPSIS = "\xE2\x80\xA6";   // U+2026

		// Largest prefix that still fits once the ellipsis is added. lo is the
		// empty prefix, which is just the ellipsis: if even that overflows we
		// return it rather than an empty line, because a blank row reads as a
		// bug and a lone ellipsis reads as a truncation.
		size_t lo = 0, hi = stops.size() - 1;
		while (lo < hi) {
			size_t mid = lo + (hi - lo + 1) / 2;
			if (textWidth(vg, style, str.substr(0, stops[mid]) + ELLIPSIS) <= maxWidth)
				lo = mid;
			else
				hi = mid - 1;
		}
		return str.substr(0, stops[lo]) + ELLIPSIS;
	}

private:
	std::string source;
	std::string result;
	float cachedWidth = -1.f;
	float cachedSize = -1.f;
	float cachedScale = -1.f;
	Face cachedFace = Face::Ui;
};

// --- shared hardware -------------------------------------------------------
/** Hex-head brass screw. The SVG is exactly 15 x 14.9989 px, matching stock
    ScrewSilver, because SvgScrew takes its box size straight from the SVG. */
struct ScrewHex : app::SvgScrew {
	ScrewHex() {
		setSvg(Svg::load(asset::plugin(pluginInstance, "res/ScrewHex.svg")));
	}
};

/** Brass-collared jacks on the stock PJ301M canvas. The stock chrome collar is
    the loudest off-palette object on a green panel; brass matches the screws.
    The output variant rings the throat in mint. */
struct PortIn : app::SvgPort {
	PortIn() {
		setSvg(Svg::load(asset::plugin(pluginInstance, "res/PortIn.svg")));
	}
};

/** The same jacks, with a thin lime line inside the throat: this one
 *  carries timing -- a clock, a trigger, a gate, a reset -- rather than
 *  a level. The band still says which way it goes. */
struct PortTrigIn : app::SvgPort {
	PortTrigIn() {
		setSvg(Svg::load(asset::plugin(pluginInstance, "res/PortTrigIn.svg")));
	}
};

struct PortTrigOut : app::SvgPort {
	PortTrigOut() {
		setSvg(Svg::load(asset::plugin(pluginInstance, "res/PortTrigOut.svg")));
	}
};
struct PortOut : app::SvgPort {
	PortOut() {
		setSvg(Svg::load(asset::plugin(pluginInstance, "res/PortOut.svg")));
	}
};

/** Every stock light derives from GrayModuleLightWidget, which hard-codes a
    #333333 socket that reads as a grey hole punched in a green panel. These
    restyle the socket as well as the emitter. */
template <typename TBase = GrayModuleLightWidget>
struct TSocketLight : TBase {
	TSocketLight() {
		this->bgColor = nvgRGBA(0x1b, 0x15, 0x1e, 0xff);
		this->borderColor = nvgRGBA(0x7b, 0x9a, 0x6d, 0xa0);
	}
};

template <typename TBase = GrayModuleLightWidget>
struct TLimeLight : TSocketLight<TBase> {
	TLimeLight() { this->addBaseColor(LIME); }
};
using LimeLight = TLimeLight<>;
template <typename TBase = GrayModuleLightWidget>
struct TMintLight : TSocketLight<TBase> {
	TMintLight() { this->addBaseColor(MINT); }
};
using MintLight = TMintLight<>;
template <typename TBase = GrayModuleLightWidget>
struct TPaperLight : TSocketLight<TBase> {
	TPaperLight() { this->addBaseColor(PAPER); }
};
using PaperLight = TPaperLight<>;
template <typename TBase = GrayModuleLightWidget>
struct TClayLight : TSocketLight<TBase> {
	TClayLight() { this->addBaseColor(CLAY); }
};
using ClayLight = TClayLight<>;
template <typename TBase = GrayModuleLightWidget>
struct TVerdictLight : TSocketLight<TBase> {
	TVerdictLight() { this->addBaseColor(MINT); this->addBaseColor(CLAY); }
};
using VerdictLight = TVerdictLight<>;

/** A light whose colour the module picks rather than the panel: three base
    colours the caller mixes by setting their brightnesses. For an indicator
    that has to be told apart from its neighbours -- one step of a sequence,
    one slot of a bank -- where a fixed ink can only say on or off. Feed it
    the components of an NVGcolor and it wears that colour; the family socket
    is kept, so it still reads as part of the panel and not as a stock LED. */
template <typename TBase = GrayModuleLightWidget>
struct TRgbLight : TSocketLight<TBase> {
	TRgbLight() {
		this->addBaseColor(nvgRGB(0xff, 0x00, 0x00));
		this->addBaseColor(nvgRGB(0x00, 0xff, 0x00));
		this->addBaseColor(nvgRGB(0x00, 0x00, 0xff));
	}
};
using RgbLight = TRgbLight<>;

/** The four corner screws, at the positions every panel in the family uses.
    Width comes from the widget's own box, so this needs no per-panel number. */
inline void addScrews(app::ModuleWidget* mw) {
	mw->addChild(createWidget<ScrewHex>(Vec(RACK_GRID_WIDTH, 0)));
	mw->addChild(createWidget<ScrewHex>(Vec(mw->box.size.x - 2 * RACK_GRID_WIDTH, 0)));
	mw->addChild(createWidget<ScrewHex>(Vec(RACK_GRID_WIDTH, RACK_GRID_HEIGHT - RACK_GRID_WIDTH)));
	mw->addChild(createWidget<ScrewHex>(Vec(mw->box.size.x - 2 * RACK_GRID_WIDTH,
	                                        RACK_GRID_HEIGHT - RACK_GRID_WIDTH)));
}

// --- silkscreen ------------------------------------------------------------
/** One word on the panel. The table itself is per-panel and lives in
    Panel.hpp; this is only its shape and how it is drawn. */
struct Label {
	float x, y, size, tracking;
	NVGcolor ink;
	int align;
	bool mirror;
	const char* text;
};

/** The style one silkscreen entry is set in. */
inline TextStyle labelStyle(const Label& l) {
	return TextStyle(Face::Ui, l.size, l.ink, l.align, l.tracking);
}

/** Draws a panel's silkscreen. Rack's nanosvg ignores <text>, so this is the
    only way a label reaches the panel. The table is passed in rather than
    referenced by name so that one definition of this widget serves all three
    panels in the plugin. */
struct Labels : widget::Widget {
	const Label* labels = NULL;
	size_t count = 0;

	void draw(const DrawArgs& args) override {
		for (size_t i = 0; i < count; i++) {
			const Label& l = labels[i];
			Vec p = mm(l.x, l.y);
			if (l.mirror)
				textMirrored(args.vg, labelStyle(l), p.x, p.y, l.text);
			else
				text(args.vg, labelStyle(l), p.x, p.y, l.text);
		}
		Widget::draw(args);
	}
};

inline void addLabels(app::ModuleWidget* mw, const Label* labels, size_t count) {
	Labels* l = new Labels;
	l->labels = labels;
	l->count = count;
	l->box.pos = Vec(0, 0);
	l->box.size = mw->box.size;
	mw->addChild(l);
}

} // namespace panel
